//! The bridge's generated files (RD27 spec §2.3.6): the page's TypeScript types, the isolation hook's command
//! table and Tauri's permission set, all from [`super::spec`] and [`super::types`]. The test checks them against
//! the interface fixtures (decision L4); with `RR_UPDATE_GENERATED=1` it also writes them out (see
//! [`output_dir`]). Where they finally live is the shell's business.

#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    reason = "test-only: a panic is how a test fails"
)]

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

use protocol::invite::ServerMode;
use protocol::status::{
    GameDataKind, InstanceKind, PlayerWhere, RegistrationMode, ServerStatus, StatusGame, StatusInstance, StatusPlayer,
};
use ts_rs::{Config, TS};

use super::spec::{self, COMMANDS, Field, SETTINGS_KEYS, Shape};
use super::types::*;
use crate::core::i18n::Language;

const BANNER: [&str; 2] = [
    "Generated by launcher-kit from crates/launcher-kit/src/bridge; edits here are lost.",
    "To regenerate: RR_UPDATE_GENERATED=1 cargo test -p launcher-kit generated",
];

const PERMISSION_SET_DESCRIPTION: &str = "Allows the page to call the bridge's commands, all of them and only them.";

/// Overrides where `RR_UPDATE_GENERATED=1` writes the files.
pub const OUTPUT_DIR_VAR: &str = "LAUNCHER_KIT_GENERATED_DIR";

/// The unions written by hand: their Rust types serialise by hand too, so ts-rs cannot see their shape.
const UNIONS: &[(&str, &str)] = &[
    ("GraphicsPreset", "-1 | 0 | 1 | 2 | 3 | 4"),
    ("ActionResult", "{ ok: true }"),
    (
        "InviteCheck",
        "{ ok: true; certificateChanged: boolean; previousFingerprint: string | null; movedFrom: string | null }",
    ),
    ("RegisterOutcome", "{ ok: true; username: string }"),
    (
        "RegionPing",
        "{ ok: true; regions: Array<RegionRtt>; reported: boolean }",
    ),
    ("EpicLibraryCheck", "{ ok: true; owned: boolean; checkedAt: string }"),
    ("GameVersionList", "{ ok: true; versions: Array<GameVersionEntry> }"),
    ("InstallOutcome", "{ ok: true; install: InstallInfo }"),
    ("GuardedList", "{ ok: true; actions: Array<GuardedActionInfo> }"),
    ("GuardedOutcome", "{ ok: true; action: GuardedActionInfo }"),
    ("ModuleListOutcome", "{ ok: true; modules: Array<ModuleView> }"),
    ("ModuleOutcome", "{ ok: true; module: ModuleView }"),
    (
        "ModuleCommandOutcome",
        "{ ok: true; text: string; data: string | null }",
    ),
    ("HistoryOutcome", "{ ok: true; page: HistoryPageView }"),
    ("RevertPlanOutcome", "{ ok: true; plan: RevertPlanView }"),
    ("RevertApplyOutcome", "{ ok: true; done: RevertDoneView }"),
    ("RealmOutcome", "{ ok: true; realm: RealmView }"),
    ("ServerDoctorOutcome", "{ ok: true; report: DoctorReportView }"),
    ("ServerConfigOutcome", "{ ok: true; config: ServerConfigView }"),
    (
        "ServerInviteListOutcome",
        "{ ok: true; invites: Array<ServerInviteEntry> }",
    ),
    ("AdminOutcome", "{ ok: true; result: AdminResultView }"),
    ("RemoteStatusOutcome", "{ ok: true; status: RemoteStatusView }"),
    ("RemoteInviteOutcome", "{ ok: true; invite: RemoteInviteView }"),
    ("RemoteExecOutcome", "{ ok: true; result: RemoteExecView }"),
];

fn declare<T: TS>(out: &mut String, cfg: &Config) {
    if let Some(docs) = T::docs() {
        out.push_str(&docs);
    }
    let _ = writeln!(out, "export {}", T::decl(cfg));
}

macro_rules! declare_all {
    ($out:expr, $cfg:expr; $($ty:ty),* $(,)?) => {
        $(declare::<$ty>($out, $cfg);)*
    };
}

fn banner(prefix: &str) -> String {
    BANNER.iter().map(|line| format!("{prefix} {line}\n")).collect()
}

/// `types.ts`: the protocol's status types, then the launcher's, then the hand-written unions and `CommandName`.
pub fn types_ts() -> String {
    // The page reads every integer as a JS number; none of them gets near 2^53.
    let cfg = Config::new().with_large_int("number");
    let cfg = &cfg;
    let mut out = banner("//");
    out.push('\n');
    declare_all!(&mut out, cfg;
        ServerMode, PlayerWhere, InstanceKind, RegistrationMode, StatusPlayer, StatusInstance, GameDataKind,
        StatusGame, ServerStatus,
        Language, GameLanguage, RuntimeProfile, Phase, ConnectProblem, GameProblem, ServerGame, Game,
        RuntimeState, ErrorCode, NoticeCode, LauncherError, TaskKind, TaskProgress, ServerInfo, SavedServerInfo,
        GameSource, DetectedGame, GameInfo, RevivedInfo, InstallMode, RuntimeFileInfo, RuntimeInfo, Settings,
        SnapshotConnect, SnapshotAccount, SnapshotRunning, SnapshotApp, Snapshot, NewsItem, Background, Branding,
        GameDataState, HostUpstream, HostSdk, HostDump, HostBuilds, HostToolchain, HostGameData, HostExports,
        HostServerMode, HostServerConfig, HostKit, HostMultipliers, HostUpdateState, HostUpdateView,
        RequirementId, RequirementState, Requirement, HostServerState, HostInvite, HostServerView,
        HostServerComponent, HostComponentPhase, HostJobKind, HostJobState, HostJob,
        ExternalTarget, HostAction, HostFolder, HostSetupRequest, RealmKind, RegionProblem, RegionRtt,
        GameVersionInstall, GameVersionOrigin, EpicManifestState, EpicVersionInfo, GameVersionEntry,
        EpicView, InstallState, InstallInfo, GuardedState, GuardedMode, GuardedActionInfo,
        ModuleRole, ModuleOrigin, ModuleRunState, ModulePortView, ModuleArgView, ModuleCommandView,
        ModuleSettingValue, ModuleSettingView, ModuleSectionView, ModulePatchSetView, ModulePaletteEntry,
        ModuleThemeView, ModuleCapabilitiesView, ModuleView,
        HistoryEntryView, HistoryPageView, RevertRowView, RevertConflictView, RevertPlanView, RevertedInView,
        RevertDoneView, RealmState, RealmSessionView, RealmView, DoctorLevel, DoctorCheckView, DoctorReportView,
        MongoMigrationState, MongoMigrationView, ServerConfigView, ServerInviteEntry,
        AdminActionKind, AdminPlayerView, AdminResultView,
        ManagedInstallView, RemoteStatusView, RemoteInviteView, RemoteExecView,
    );
    for (name, ok) in UNIONS {
        if *name == "GraphicsPreset" {
            let _ = writeln!(out, "export type {name} = {ok};");
        } else {
            let _ = writeln!(
                out,
                "export type {name} = {ok} | {{ ok: false; error: LauncherError }};"
            );
        }
    }
    let names: Vec<String> = COMMANDS.iter().map(|c| quote(c.name)).collect();
    let _ = writeln!(out, "export type CommandName = {};", names.join(" | "));
    out
}

fn quote(text: &str) -> String {
    serde_json::to_string(text).expect("a string serialises")
}

fn shape_js(shape: &Shape) -> String {
    match shape {
        Shape::Text { max } => format!("{{ kind: \"text\", max: {max} }}"),
        Shape::OptionalText { max } => format!("{{ kind: \"optionalText\", max: {max} }}"),
        Shape::Flag => "{ kind: \"flag\" }".to_owned(),
        Shape::Index { max } => format!("{{ kind: \"index\", max: {max} }}"),
        Shape::Name(names) => {
            let names: Vec<String> = names.iter().map(|n| quote(n)).collect();
            format!("{{ kind: \"name\", names: [{}] }}", names.join(", "))
        }
        Shape::Number { min, max } => format!("{{ kind: \"number\", min: {min}, max: {max} }}"),
        Shape::Object { nullable, fields } => {
            format!(
                "{{ kind: \"object\", nullable: {nullable}, fields: {} }}",
                fields_js(fields)
            )
        }
        Shape::SettingsPatch => "{ kind: \"settingsPatch\" }".to_owned(),
        Shape::Channel => "{ kind: \"channel\" }".to_owned(),
    }
}

fn fields_js(fields: &[Field]) -> String {
    if fields.is_empty() {
        return "{}".to_owned();
    }
    let fields: Vec<String> = fields
        .iter()
        .map(|f| format!("{}: {}", quote(f.name), shape_js(&f.shape)))
        .collect();
    format!("{{ {} }}", fields.join(", "))
}

/// `commands.js`: the isolation hook's command table and the settings keys.
pub fn commands_js() -> String {
    let mut out = banner("//");
    out.push_str("window.__RR_COMMANDS__ = {\n");
    for command in COMMANDS {
        let _ = writeln!(out, "  {}: {},", quote(command.name), fields_js(command.args));
    }
    out.push_str("};\n");
    let keys: Vec<String> = SETTINGS_KEYS.iter().map(|k| quote(k)).collect();
    let _ = writeln!(out, "window.__RR_SETTINGS_KEYS__ = [{}];", keys.join(", "));
    out
}

/// `app-commands.toml`: Tauri's permission set allowing exactly the table's commands.
pub fn app_commands_toml() -> String {
    let mut out = banner("#");
    out.push_str("\n[[set]]\nidentifier = \"app-commands\"\n");
    let _ = writeln!(out, "description = {}", quote(PERMISSION_SET_DESCRIPTION));
    out.push_str("permissions = [\n");
    for command in COMMANDS {
        let _ = writeln!(out, "  \"allow-{}\",", command.name.replace('_', "-"));
    }
    out.push_str("]\n");
    out
}

/// Which generated file a text is, for [`normalise`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum File {
    /// `types.ts`.
    Types,
    /// `commands.js`.
    Commands,
    /// `app-commands.toml`.
    Permissions,
}

/// The fixtures' normal form (`tests/fixtures/bridge/README.md`): only names, shapes and limits remain.
pub fn normalise(text: &str, file: File) -> String {
    let text = text.replace("\r\n", "\n");
    let mut body = text.as_str();
    while body.starts_with("//") || body.starts_with('#') {
        body = body.find('\n').map_or("", |i| &body[i + 1..]);
    }
    match file {
        File::Types => strip_doc_comments(body),
        File::Commands => body.to_owned(),
        File::Permissions => body
            .split_inclusive('\n')
            .filter(|line| !line.starts_with("description = \""))
            .collect(),
    }
}

/// Drops every `/** … */` and the line break after it. One that ts-rs put inside a declaration (a field's or a
/// variant's) also takes the line break ts-rs put before it; one that starts a declaration (a type's) does not.
fn strip_doc_comments(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut rest = text;
    while let Some(start) = rest.find("/**") {
        let Some(len) = rest[start..].find("*/") else { break };
        let mut end = start + len + 2;
        if rest[end..].starts_with('\n') {
            end += 1;
        }
        let before = &rest[..start];
        let starts_declaration = rest[end..].starts_with("export ") || before.is_empty() && out.is_empty();
        let before = match before.strip_suffix('\n') {
            Some(trimmed) if !starts_declaration && !trimmed.is_empty() && !trimmed.ends_with('\n') => trimmed,
            _ => before,
        };
        out.push_str(before);
        rest = &rest[end..];
    }
    out.push_str(rest);
    out
}

fn fixture(name: &str) -> String {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/bridge")
        .join(name);
    std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

/// Where the generated files are kept (committed; the shell and `bun run restricted-data` copy them from here), or
/// [`OUTPUT_DIR_VAR`]. Never under `restricted/` or `ui/`: those take copies.
pub fn output_dir() -> PathBuf {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let dir = std::env::var_os(OUTPUT_DIR_VAR).map_or_else(
        || Path::new(env!("CARGO_MANIFEST_DIR")).join("generated"),
        PathBuf::from,
    );
    let resolved = std::path::absolute(&dir).unwrap_or_else(|_| dir.clone());
    for forbidden in ["restricted", "ui"] {
        let forbidden = std::path::absolute(root.join(forbidden)).unwrap_or_else(|_| root.join(forbidden));
        assert!(
            !normalised_path(&resolved).starts_with(normalised_path(&forbidden)),
            "{OUTPUT_DIR_VAR} must not point into {}",
            forbidden.display()
        );
    }
    resolved
}

fn normalised_path(path: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for part in path.components() {
        match part {
            std::path::Component::ParentDir => {
                out.pop();
            }
            std::path::Component::CurDir => {}
            other => out.push(other),
        }
    }
    out
}

fn outputs() -> [(&'static str, File, String); 3] {
    [
        ("types.ts", File::Types, types_ts()),
        ("commands.js", File::Commands, commands_js()),
        ("app-commands.toml", File::Permissions, app_commands_toml()),
    ]
}

#[test]
fn generated_files_match_the_interface_fixtures() {
    for (name, file, text) in outputs() {
        let expected = fixture(name);
        assert_eq!(
            normalise(&expected, file),
            expected,
            "{name}: the fixture is not in normal form"
        );
        let actual = normalise(&text, file);
        if actual != expected {
            let line = actual.lines().zip(expected.lines()).position(|(a, e)| a != e);
            panic!(
                "{name} differs from the fixture at line {}:\n  generated: {:?}\n  fixture:   {:?}",
                line.map_or(0, |l| l + 1),
                line.and_then(|l| actual.lines().nth(l)),
                line.and_then(|l| expected.lines().nth(l)),
            );
        }
    }
}

/// The committed copies are the generator's output; `RR_UPDATE_GENERATED=1` rewrites them.
#[test]
fn generated_files_are_current() {
    let dir = output_dir();
    let update = std::env::var_os("RR_UPDATE_GENERATED").is_some_and(|v| v == "1");
    let mut stale = Vec::new();
    for (name, _, text) in outputs() {
        let target = dir.join(name);
        let current = std::fs::read_to_string(&target)
            .unwrap_or_default()
            .replace("\r\n", "\n");
        if current == text {
            continue;
        }
        if update {
            std::fs::create_dir_all(&dir).unwrap();
            std::fs::write(&target, text).unwrap();
        } else {
            stale.push(target.display().to_string());
        }
    }
    assert!(
        stale.is_empty(),
        "stale generated files (run RR_UPDATE_GENERATED=1 cargo test -p launcher-kit generated): {stale:?}"
    );
}

#[test]
fn generated_docs_are_kept_until_normalised() {
    let types = types_ts();
    assert!(types.contains("/**"), "the types carry their doc comments");
    assert!(types.starts_with("// "));
    assert!(app_commands_toml().contains("description = "));
}

#[test]
fn generated_output_names_every_command() {
    let (types, commands, permissions) = (types_ts(), commands_js(), app_commands_toml());
    for command in COMMANDS {
        assert!(types.contains(&quote(command.name)), "{}", command.name);
        assert!(
            commands.contains(&format!("  {}: ", quote(command.name))),
            "{}",
            command.name
        );
        assert!(
            permissions.contains(&format!("\"allow-{}\"", command.name.replace('_', "-"))),
            "{}",
            command.name
        );
    }
}

#[test]
fn generated_doc_comments_normalise_away() {
    let documented = "\nexport type A = { \n/**\n * a\n */\nx: string, };\n/**\n * B\n */\nexport type B = \"b\";\n";
    assert_eq!(
        normalise(documented, File::Types),
        "\nexport type A = { x: string, };\nexport type B = \"b\";\n"
    );
    assert_eq!(
        normalise("/** T */\nexport type T = 1;\n", File::Types),
        "export type T = 1;\n"
    );
}

/// Each name list in [`spec`] is its wire enum's names, in order.
#[test]
fn generated_name_lists_are_the_enums() {
    fn union<T: TS>() -> String {
        let decl = T::decl(&Config::new());
        strip_doc_comments(&decl)
            .trim_start_matches(&format!("type {} = ", T::ident(&Config::new())))
            .trim_end_matches(';')
            .to_owned()
    }
    fn listed(names: &[&str]) -> String {
        names.iter().map(|n| quote(n)).collect::<Vec<_>>().join(" | ")
    }
    assert_eq!(union::<InstallMode>(), listed(spec::INSTALL_MODES));
    assert_eq!(union::<ExternalTarget>(), listed(spec::EXTERNAL_TARGETS));
    assert_eq!(union::<HostAction>(), listed(spec::HOST_ACTIONS));
    assert_eq!(union::<HostFolder>(), listed(spec::HOST_FOLDERS));
    assert_eq!(union::<HostServerMode>(), listed(spec::SERVER_MODES));
    assert_eq!(union::<RealmKind>(), listed(spec::REALM_KINDS));
    assert_eq!(union::<AdminActionKind>(), listed(spec::ADMIN_ACTIONS));
    let full = SettingsPatch {
        graphics: Some(GraphicsPreset::UNSET),
        windowed: Some(true),
        streamer_mode: Some(true),
        host_tools: Some(true),
        language: Some(Language::En),
        game_language: Some(GameLanguage::Auto),
        runtime_profile: Some(RuntimeProfile::Production),
        game_edition: Some(Game::Reborn),
        minimize_to_tray: Some(true),
        close_to_tray: Some(true),
        show_game_console: Some(true),
    };
    let value = serde_json::to_value(full).unwrap();
    let keys: Vec<&str> = value.as_object().unwrap().keys().map(String::as_str).collect();
    assert_eq!(keys, SETTINGS_KEYS);
}
